 11	/**
 12	 * Behaviors from prompt.md, ordered simple -> complex.
 13	 *
 14	 * Observable contract: every behavior is observed through the CLI scenario
 15	 * protocol (JSON on stdin, JSON on stdout, non-zero exit plus stderr text for
 16	 * rejections), because that is the only contract the specification fixes.
 17	 *
 18	 * Adopted readings where the specification leaves a choice:
 19	 *  - "alike" components means components of exactly the same type.
 20	 *  - the 3-component block requires exactly 3 of a type (4 runes -> no block).
 21	 *  - the first-insurance surcharge applies to every quote's policy base
 22	 *    premium, regardless of customer history.
 23	 *  - rejections are observable as a non-zero CLI exit status with a non-empty
 24	 *    stderr description and no results on stdout.
 25	 */
 26	class ClaimOfficeTest {
 27	
 28	    // ---------- processing fee and single-item base premiums ----------
 29	
 30	    @Test
 31	    void emptyItemListCostsOnlyTheProcessingFee() {
 32	        String stdout = runOffice("{\"customer\":{\"yearsWithMHPCO\":0},"
 33	                + "\"steps\":[{\"op\":\"quote\",\"items\":[]}]}");
 34	
 35	        assertEquals("{\"results\":[{\"premium\":5}]}", stdout);
 36	    }
 37	
 38	    private static String runOffice(String scenario) {
 39	        ByteArrayOutputStream captured = new ByteArrayOutputStream();
 40	        new ClaimOfficeCli().run(new ByteArrayInputStream(scenario.getBytes(StandardCharsets.UTF_8)),
 41	                new PrintStream(captured, true, StandardCharsets.UTF_8));
 42	        return captured.toString(StandardCharsets.UTF_8).trim();
 43	    }
